1090	template <int N, int64_t... Shapes>
1091	struct GetNthShape {
1092	    static constexpr int64_t value = []() {
1093	        int idx = 0;
1094	        int64_t val = 0;
1095	        ((idx == N ? (val = Shapes, idx++) : idx++), ...);
1096	        return val;
1097	    }();
1098	};
1099	
1100	template <int64_t... Shapes>
1101	struct CountDynamicDim {
1102	    static constexpr int value = []() {
1103	        int count = 0;
1104	        count += (GetNthShape<0, Shapes...>::value == DYNAMIC ? 1 : 0);
1105	        count += (GetNthShape<1, Shapes...>::value == DYNAMIC ? 1 : 0);
1106	        count += (GetNthShape<2, Shapes...>::value == DYNAMIC ? 1 : 0);
1107	        count += (GetNthShape<3, Shapes...>::value == DYNAMIC ? 1 : 0);
1108	        count += (GetNthShape<4, Shapes...>::value == DYNAMIC ? 1 : 0);
1109	        count += (GetNthShape<5, Shapes...>::value == DYNAMIC ? 1 : 0);
1110	        return count;
1111	    }();
1112	};
1113	
1114	template <int DimIdx, int64_t... Shapes>
1115	struct AssignDynamicDim {
1116	    static void apply(int64_t* shape, const int* vals, int& val_idx)
1117	    {
1118	        if constexpr (GetNthShape<DimIdx, Shapes...>::value == DYNAMIC) {
1119	            shape[DimIdx] = vals[val_idx++];
1120	        }
1121	        if constexpr (DimIdx + 1 < static_cast<int>(MAX_CONVTILE_DIM)) {
1122	            AssignDynamicDim<DimIdx + 1, Shapes...>::apply(shape, vals, val_idx);
1123	        }
1124	    }
1125	};
