1784	    Tile<Loc_, Element_, Rows_, Cols_, BFractal_, RowValid_, ColValid_, SFractal_, SFractalSize_, PadVal_, Compact_>>
1785	    : std::true_type {
1786	    static constexpr SLayout layout_enum = SFractal_;
1787	};
1788	
1789	template <typename T>
1790	constexpr bool is_boxed_tile = is_tile<T>::value && (is_tile<T>::layout_enum != SLayout::NoneBox);
1791	
1792	template <typename T>
1793	struct is_conv_tile : std::false_type {};
1794	template <TileType Loc_, typename Element_, const int BufferSize_, Layout Layout_, typename Shape_>
1795	struct is_conv_tile<ConvTile<Loc_, Element_, BufferSize_, Layout_, Shape_>> : std::true_type {};
1796	
1797	template <typename tile_shape>
1798	struct is_Nz_layout {
1799	    static constexpr bool value = !tile_shape::isRowMajor && tile_shape::isBoxedLayout && tile_shape::isInnerRowMajor;
1800	};
1801	
1802	template <typename tile_shape>
1803	struct is_Zn_layout {
1804	    static constexpr bool value = tile_shape::isRowMajor && tile_shape::isBoxedLayout && tile_shape::isInnerColMajor;
1805	};
1806	
1807	template <typename tile_shape>
1808	struct is_Zz_layout {
1809	    static constexpr bool value = tile_shape::isRowMajor && tile_shape::isBoxedLayout && tile_shape::isInnerRowMajor;
1810	};
1811	template <typename T>
1812	constexpr bool is_conv_tile_v = is_conv_tile<T>::value;
1813	
1814	template <typename T>
1815	constexpr bool is_global_data_v = is_global<T>::value;
1816	
1817	template <typename T>
1818	constexpr bool is_tile_data_v = is_tile<T>::value;
1819	
1820	template <typename T>
1821	constexpr bool is_boxed_data_v = is_boxed_tile<T>;
1822	
1823	// Maps logical tile coordinates to the backing storage offset.
1824	template <typename TileT>
1825	PTO_INTERNAL size_t GetTileOffset(int row, int col)
1826	{
1827	    static_assert(is_tile_data_v<TileT>, "tile_offset only accepts Tile types.");
1828	    if constexpr (!TileT::isBoxedLayout) {
1829	        return row * TileT::RowStride + col * TileT::ColStride;
1830	    } else {
1831	        int BlockRow = row / TileT::InnerRows;
1832	        int BlockCol = col / TileT::InnerCols;
1833	        int InnerRow = row % TileT::InnerRows;
1834	        int InnerCol = col % TileT::InnerCols;
1835	        static constexpr int BlockNumRow = TileT::Rows / TileT::InnerRows;
1836	        static constexpr int BlockNumCol = TileT::Cols / TileT::InnerCols;
1837	        if constexpr (is_Nz_layout<TileT>::value) {
1838	            return (BlockNumRow * BlockCol + BlockRow) * TileT::InnerNumel + InnerRow * TileT::InnerCols + InnerCol;
1839	        } else if constexpr (is_Zn_layout<TileT>::value) {
1840	            return (BlockNumCol * BlockRow + BlockCol) * TileT::InnerNumel + InnerCol * TileT::InnerRows + InnerRow;
1841	        } else if constexpr (is_Zz_layout<TileT>::value) {
1842	            return (BlockNumCol * BlockRow + BlockCol) * TileT::InnerNumel + InnerRow * TileT::InnerCols + InnerCol;
1843	        } else {
1844	            static_assert(
1845	                sizeof(TileT) == 0, "Unsupported layout in Tile, fractal tiles should be "
1846	                                    "Nz or Zn layout.");
1847	        }
1848	    }
1849	}
1850	
1851	} // namespace pto
1852	
1853	#endif
1854

